use crate::{catalog,model::*,rules::*,unit_support::*};
use crate::bq067 as b;
fn setup(parked:bool)->(Game,String){let mut g=game();g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));g.players[0].honor=2;let c=g.make_card("BQ046",0);let id=c.id.clone();g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),card:if parked{Some(c.clone())}else{None},rest:2});if !parked{g.regions[0].cards.push(c);}fund(&mut g,0,"BQ064",8);(g,id)}
fn attach(g:&mut Game)->String{let id=held(g,b::ID,0);act(g,0,Action{card_id:Some(id),target_id:Some("society:p0".into()),..Action::new("play")});crate::jc029_tests::pass_top(g);g.attachments.iter().rev().find(|a|a.card.definition==b::ID).unwrap().card.id.clone()}
fn action(id:&str)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::KEY.into()),..Action::new("activate")}}
fn invalid(g:&Game,bad:&Game){assert!(Game::from_persisted(&serde_json::to_string(bad).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=bad.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn bq067_live_defense_counts_actual_rest_and_sources_not_parked_or_hidden(){let(mut g,id)=setup(false);let a=attach(&mut g);assert!(!catalog::card(b::ID).supported);assert_eq!(g.defense(g.board(&id).unwrap().1,0),4);g.core_zones[0].rest=4;assert_eq!(g.defense(g.board(&id).unwrap().1,0),6);let _b=attach(&mut g);assert_eq!(g.defense(g.board(&id).unwrap().1,0),11);g.attachments.iter_mut().find(|x|x.card.id==a).unwrap().card.face_down=true;assert_eq!(g.defense(g.board(&id).unwrap().1,0),6);g.board_mut(&id).unwrap().controller=1;assert_eq!(g.bq067_defense(g.board(&id).unwrap().1),0);g.board_mut(&id).unwrap().controller=0;g.board_mut(&id).unwrap().face_down=true;assert_eq!(g.bq067_defense(g.board(&id).unwrap().1),0);let(mut p,_)=setup(true);attach(&mut p);assert_eq!(p.bq067_defense(p.core_zones[0].card.as_ref().unwrap()),0);restore(&mut p);}
#[test]fn bq067_real_honor_and_sacrifice_grant_barrier_then_expire(){let(mut g,id)=setup(false);let a=attach(&mut g);act(&mut g,0,action(&a));assert_eq!(g.players[0].honor,1);assert!(g.players[0].graveyard.iter().any(|c|c.definition==b::ID));assert_eq!(g.defense(g.board(&id).unwrap().1,0),1);assert!(!g.has_barrier(g.board(&id).unwrap().1));crate::jc029_tests::pass_top(&mut g);assert!(g.has_barrier(g.board(&id).unwrap().1));assert!(!g.targetable(2,g.board(&id).unwrap().1));assert!(g.targetable(0,g.board(&id).unwrap().1));restore(&mut g);for _ in 0..400{if g.turn>1{break;}if g.pending.is_some(){let p=g.pending.clone().unwrap();if p.choice.kind=="investigation"{let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();act(&mut g,p.seat,Action{choice_id:Some(p.choice.id),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});}else{choose(&mut g,p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}}else{let seat=(0..4).find(|s|g.legal_actions(*s).iter().any(|a|a.action.kind=="pass")).unwrap();act(&mut g,seat,Action::new("pass"));}}assert!(g.turn>1);assert!(g.bq067_grants.is_empty());assert!(!g.has_barrier(g.board(&id).unwrap().1));}
#[test]fn bq067_payment_rejects_currency_substitution_and_other_actor(){let(mut g,_)=setup(false);let a=attach(&mut g);g.players[0].honor=0;reject(&mut g,0,action(&a));assert!(g.attachments.iter().any(|x|x.card.id==a));g.players[0].honor=2;reject(&mut g,1,action(&a));let mut bad=action(&a);bad.target_id=Some("society:p0".into());reject(&mut g,0,bad);}
#[test]fn bq067_actual_core_at_resolution_and_cold_restore_reject_corruption(){let(mut g,id)=setup(true);let a=attach(&mut g);act(&mut g,0,action(&a));let c=g.core_zones[0].card.take().unwrap();g.regions[0].cards.push(c);crate::jc029_tests::pass_top(&mut g);assert!(g.has_barrier(g.board(&id).unwrap().1));for n in 0..5{let mut x=g.clone();match n{0=>x.bq067_grants[0].turn+=1,1=>x.bq067_grants[0].recipient.owner=1,2=>x.bq067_grants[0].frame.already_paid.clear(),3=>x.bq067_grants.push(x.bq067_grants[0].clone()),_=>x.effects.push_back(Effect::Frame{frame:x.bq067_grants[0].frame.clone()})}invalid(&g,&x);}let c=g.remove_board(&id).unwrap().1;let c=g.fresh(c);g.regions[0].cards.push(c);assert!(g.bq067_grants.is_empty());restore(&mut g);}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn select(g:&Game,p:&Pending)->Vec<String>{let mut o=p.choice.options.iter().collect::<Vec<_>>();o.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&matches!(c.definition.as_str(),"BQ067"|"BQ048"|"BQ064"|"BQ049")));o.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}
fn natural()->serde_json::Value{use crate::{deck,abi112_review_play_tests::Trace};fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="bq067-natural-50-plus-core".into();d.society_id=Some("MSBQ02".into());d.core_card_id=Some("BQ046".into());d.cards=[("BQ067",3),("BQ064",3),("BQ048",3),("BQ050",3),("BQ049",3),("JC125",35)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if ["BQ067","BQ046","BQ048","BQ050","BQ049"].contains(&c.id.as_str()){c.supported=true;}}let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSBQ02").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq067".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for seat in 1..4{g.join(format!("P{seat}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
 let(seed,g)=(1..4097).find_map(|seed|{let g=construct(seed);["BQ067","BQ064","BQ048","BQ049"].iter().all(|id|g.players[0].hand.iter().any(|c|c.definition==*id)).then_some((seed,g))}).expect("actual dealt attachment and both loyalty assets");let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"bq067-natural-fifty-plus-core-honor-barrier".into(),770);let mut done=false;for _ in 0..1600{if let Some(p)=t.room.game.pending.clone(){trace_choice(&mut t,&p);continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if g.players[0].assets.len()<5{let wanted=match g.players[0].assets.len(){0=>"BQ064",1=>"BQ048",_=>"JC125"};legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==wanted)))}else if !g.attachments.iter().any(|a|a.card.definition==b::ID)&&!done{legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)))}else if g.players[0].honor==0{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::bq049::KEY)&&a.action.option.as_deref()==Some("mobility"))}else if g.core_zones[0].card.is_some(){legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_deref()==g.core_zones[0].card.as_ref().map(|c|c.id.as_str()))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY))};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(b::KEY){done=true;}t.action(0,a.action.clone());}else{t.pass();}}
 if !done {let g=&t.room.game;eprintln!("natural incomplete turn={} honor={} assets={} hand={:?} core={:?}",g.turn,g.players[0].honor,g.players[0].assets.len(),g.players[0].hand.iter().map(|c|&c.definition).collect::<Vec<_>>(),g.core_zones);if let Ok(p)=std::env::var("BQ067_DEBUG_OUT"){std::fs::write(p,serde_json::to_vec(g).unwrap()).unwrap();}}assert!(done);let c=t.room.game.regions.iter().flat_map(|r|&r.cards).find(|c|c.definition=="BQ046").unwrap();assert!(t.room.game.has_barrier(c));let mut v=t.value();v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"separateCore":1,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn bq067_native_natural_and_prepared_export(){use crate::abi112_review_play_tests::Trace;let mut cases=vec![natural()];for(parked,index)in[(false,771),(true,772)]{let(mut g,id)=setup(parked);let a=attach(&mut g);let mut t=Trace::new_preserving_rng(g,format!("bq067-prepared-parked-{parked}"),index);t.action(0,action(&a));for _ in 0..60{if let Some(p)=t.room.game.pending.clone(){trace_choice(&mut t,&p);}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}else{t.pass();}}assert_eq!(!t.room.game.bq067_grants.is_empty(),!parked);if !parked{assert!(t.room.game.has_barrier(t.room.game.board(&id).unwrap().1));}cases.push(duplicate(t.value()));}let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/bq067.rs",include_bytes!("bq067.rs").as_slice()),("rust-game/src/bq067_tests.rs",include_bytes!("bq067_tests.rs").as_slice()),("rust-game/src/core_zone.rs",include_bytes!("core_zone.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(path)=std::env::var("BQ067_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

fn trace_choice(t:&mut crate::abi112_review_play_tests::Trace,p:&Pending){if p.choice.kind=="investigation"||p.choice.kind=="order" {let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id.clone()),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});}else{let ids=select(&t.room.game,p);t.choose(ids);}}
#[test]fn bq067_hidden_successor_loses_resolved_grant_and_source_departure_stops_aura(){let(mut g,id)=setup(false);let a=attach(&mut g);act(&mut g,0,action(&a));crate::jc029_tests::pass_top(&mut g);g.board_mut(&id).unwrap().controller=2;assert!(g.has_barrier(g.board(&id).unwrap().1));g.board_mut(&id).unwrap().controller=0;assert!(g.hide_in_place(&id));assert!(g.bq067_grants.is_empty());let c=g.regions[0].cards.iter().find(|c|c.definition=="BQ046").unwrap();assert!(!g.has_barrier(c));assert_eq!(g.bq067_defense(c),0);restore(&mut g);let(mut g,id)=setup(false);let a=attach(&mut g);g.remove_dead(&a,RemovalCause::Destroy);g.drive().unwrap();assert_eq!(g.defense(g.board(&id).unwrap().1,0),1);restore(&mut g);}
